class EventManager {
  private final java.util.TreeSet<Long> ordered = new java.util.TreeSet<>();
  private final java.util.HashMap<Integer, Integer> priority = new java.util.HashMap<>();
  private static final long BASE = 1_000_000_001L;

  private static long key(int id, int p) {
    return ((BASE - p) << 30) | id;
  }

  public EventManager(int[][] events) {
    for (int[] e : events) {
      priority.put(e[0], e[1]);
      ordered.add(key(e[0], e[1]));
    }
  }

  public void updatePriority(int eventId, int newPriority) {
    ordered.remove(key(eventId, priority.get(eventId)));
    priority.put(eventId, newPriority);
    ordered.add(key(eventId, newPriority));
  }

  public int pollHighest() {
    if (ordered.isEmpty()) return -1;
    long k = ordered.pollFirst();
    int id = (int) (k & ((1L << 30) - 1));
    priority.remove(id);
    return id;
  }
}
